"use strict";

import Game from './core/Game.js';
import { setupAudio, preloadAssets } from './core/Assets.js';

// Game configuration
const config = {
  canvas: 'game-canvas',
  width: 1280,
  height: 720,
  tileSize: 32,
  fps: 60,
  mapSize: { width: 50, height: 50 },
  playerColor: '#3498db',
  enemyColor: '#e74c3c'
};

// Race definitions
const races = {
  human: {
    name: 'Human',
    color: '#3498db',
    primaryResource: 'gold',
    units: ['worker', 'archer', 'swordsman', 'knight'],
    buildings: ['townhall', 'barracks', 'farm', 'mine'],
    startLocation: { x: 100, y: 100 }
  },
  orc: {
    name: 'Orc',
    color: '#e67e22',
    primaryResource: 'guldan',
    units: ['grunt', 'axeman', 'siege'],
    buildings: ['stronghold', 'workshop', 'lumber mill', 'foundry'],
    startLocation: { x: 1100, y: 500 }
  },
  undead: {
    name: 'Undead',
    color: '#95a5a6',
    primaryResource: 'souls',
    units: ['skeleton', 'zombie', 'wraith'],
    buildings: ['crypt', 'necropolis', 'catacomb', 'graveyard'],
    startLocation: { x: 1100, y: 100 }
  }
};

// Game state
let game = null;
let currentPlayer = 'human';
let isGameRunning = false;

// Initialize game
declare function initGame() {
  if (game) {
    game.destroy();
  }

  setupAudio();
  preloadAssets()
    .then(() => {
      game = new Game(config, races);
      game.start();
      isGameRunning = true;
      console.log('2D RTS Game initialized successfully!');
    })
    .catch(error => {
      console.error('Failed to initialize game:', error);
      // Retry after delay
      setTimeout(initGame, 2000);
    });
}

// Game loop integration
declare function updateGame(deltaTime) {
  if (game && isGameRunning) {
    game.update(deltaTime);
  }
}

// Handle window resize
declare function handleResize() {
  const canvas = document.getElementById(config.canvas);
  if (canvas) {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    if (game) {
      game.resize(window.innerWidth, window.innerHeight);
    }
  }
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', () => {
  // Create canvas if it doesn't exist
  const existingCanvas = document.getElementById(config.canvas);
  if (!existingCanvas) {
    const canvas = document.createElement('canvas');
    canvas.id = config.canvas;
    canvas.style.position = 'absolute';
    canvas.style.top = '0';
    canvas.style.left = '0';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    document.body.appendChild(canvas);
  }

  // Initialize game
  initGame();

  // Setup window resize handler
  window.addEventListener('resize', handleResize);
});

// Export for testing and debugging
export { config, races, game, currentPlayer, updateGame, initGame };

"use strict";

import Engine from './Engine.js';
import InputManager from './InputManager.js';
import ResourceManager from './ResourceManager.js';
import MapManager from './MapManager.js';
import UIManager from './UIManager.js';
import AudioManager from './AudioManager.js';

class Game {
  constructor(config, races) {
    this.config = config;
    this.races = races;
    this.engine = null;
    this.inputManager = null;
    this.resourceManager = null;
    this.mapManager = null;
    this.uiManager = null;
    this.audioManager = null;
    this.gameLoop = null;
    this.lastTime = 0;
    this.deltaTime = 0;
    this.isRunning = false;
    this.currentPhase = 'lobby'; // lobby, playing, paused, gameover
    this.players = {};
    this.currentTurn = 'human';
    this.resources = {};

    this.initializeComponents();
  }

  initializeComponents() {
    // Initialize core systems
    this.engine = new Engine(this.config.canvas, this.config.width, this.config.height);
    this.inputManager = new InputManager();
    this.resourceManager = new ResourceManager();
    this.mapManager = new MapManager(this.config.mapSize, this.config.tileSize);
    this.uiManager = new UIManager(this.config.width, this.config.height);
    this.audioManager = new AudioManager();

    // Setup event listeners
    this.setupEventListeners();

    // Initialize players and resources
    this.initializePlayers();
    this.initializeResources();
  }

  setupEventListeners() {
    this.inputManager.on('unitSelected', (unit) => {
      this.uiManager.updateUnitPanel(unit);
    });

    this.inputManager.on('buildingConstructed', (building) => {
      this.uiManager.updateBuildingPanel(building);
    });

    this.inputManager.on('resourceGathered', (resource) => {
      this.uiManager.updateResourcePanel(resource);
    });
  }

  initializePlayers() {
    Object.entries(this.races).forEach(([key, race]) => {
      this.players[race.name.toLowerCase()] = {
        id: key,
        name: race.name,
        race: race.name.toLowerCase(),
        color: race.color,
        resources: {
          gold: 100,
          wood: 50,
          stone: 50
        },
        units: [],
        buildings: [],
        townHall: null,
        startLocation: race.startLocation
      };
    });
  }

  initializeResources() {
    this.resources = {
      gold: { amount: 0, rate: 0, sources: [] },
      wood: { amount: 0, rate: 0, sources: [] },
      stone: { amount: 0, rate: 0, sources: [] }
    };
  }

  start() {
    if (this.isRunning) return;

    this.isRunning = true;
    this.lastTime = performance.now();
    this.currentPhase = 'playing';

    // Start game loop
    this.gameLoop = this.gameLoop.bind(this);
    this.gameLoop(this.lastTime);

    // Initialize map with terrain
    this.mapManager.initializeTerrain(this.players);

    // Start AI for opponents
    this.startAI();

    // Notify UI
    this.uiManager.setGameState(this.currentPhase);
    this.audioManager.play('music', { loop: true });
  }

  gameLoop(currentTime) {
    if (!this.isRunning) return;

    this.deltaTime = Math.min((currentTime - this.lastTime) / 1000, 0.1);
    this.lastTime = currentTime;

    // Update game systems
    this.updateGameSystems();
    this.updateUI();
    this.checkWinConditions();

    // Schedule next frame
    this.gameLoopId = requestAnimationFrame(this.gameLoop.bind(this));
  }

  updateGameSystems() {
    // Update engine (rendering)
    this.engine.clear();

    // Update game systems
    this.mapManager.update(this.deltaTime);
    this.inputManager.update(this.deltaTime);
    this.resourceManager.update(this.deltaTime, this.resources);

    // Update all players
    Object.values(this.players).forEach(player => {
      this.updatePlayer(player, this.deltaTime);
    });

    // Update units and buildings
    this.updateUnits();
    this.updateBuildings();

    // Render
    this.render();
  }

  updatePlayer(player, deltaTime) {
    // AI behavior for non-human players
    if (player.id !== 'human') {
      this.updateAI(player, deltaTime);
    } else {
      // Human player actions handled via input
      this.updateHumanPlayer(player, deltaTime);
    }
  }

  updateHumanPlayer(player, deltaTime) {
    // Handle human player input and actions
    // This would integrate with the input manager
    // For now, it's a placeholder
  }

  updateUnits() {
    const allUnits = [];
    Object.values(this.players).forEach(player => {
      allUnits.push(...player.units);
    });

    allUnits.forEach(unit => {
      unit.update(this.deltaTime);
      unit.checkCollisions(allUnits);
    });
  }

  updateBuildings() {
    const allBuildings = [];
    Object.values(this.players).forEach(player => {
      allBuildings.push(...player.buildings);
    });

    allBuildings.forEach(building => building.update(this.deltaTime));
  }

  updateAI(player, deltaTime) {
    // Simple AI behavior - can be enhanced
    // For now, just basic resource gathering and unit production

    // Build if needed
    if (this.canBuild(player)) {
      this.buildStructure(player);
    }

    // Train units if needed
    if (this.canTrainUnits(player)) {
      this.trainUnits(player);
    }

    // Attack if enemy in range
    this.attackEnemies(player);
  }

  canBuild(player) {
    // Check resources and building queue
    return player.resources.gold >= 100 && player.resources.wood >= 50;
  }

  buildStructure(player) {
    // Find location to build
    const location = this.findBuildLocation(player);
    if (location && location.valid) {
      const buildingType = this.selectBuildingType(player);
      if (buildingType) {
        // Deduct resources
        player.resources.gold -= 100;
        player.resources.wood -= 50;

        // Create building
        const building = {
          type: buildingType,
          location: location,
          owner: player.name,
          health: 100,
          maxHealth: 100,
          update: () => {},
          takeDamage: (amount) => {},
          isDestroyed: () => false
        };

        player.buildings.push(building);
        this.mapManager.setTerrain(location.x, location.y, 'building');
      }
    }
  }

  canTrainUnits(player) {
    // Check if can train units
    return player.resources.gold >= 50 && player.townHall?.operational;
  }

  trainUnits(player) {
    // Select unit type based on building
    const building = player.townHall;
    if (!building) return;

    const unitType = this.selectUnitType(player, building.type);
    if (unitType && player.resources.gold >= 50) {
      // Create unit
      const unit = this.createUnit(player, unitType);

      player.units.push(unit);
      player.resources.gold -= 50;
    }
  }

  attackEnemies(player) {
    // Simple AI attack behavior
    Object.values(this.players).forEach(otherPlayer => {
      if (otherPlayer.name !== player.name) {
        player.units.forEach(unit => {
          if (unit.canAttack()) {
            const target = this.findTarget(unit, otherPlayer);
            if (target && unit.attack(target)) {
              this.audioManager.play('attack');
            }
          }
        });
      }
    });
  }

  createUnit(player, unitType) {
    const startPos = { ...player.startLocation };
    const unit = {
      type: unitType,
      owner: player.name,
      location: startPos,
      health: 100,
      maxHealth: 100,
      attack: 10,
      range: 64,
      speed: 100,
      isMoving: false,
      target: null,

      update: (deltaTime) => {
        if (this.isMoving && this.target) {
          const dx = this.target.location.x - this.location.x;
          const dy = this.target.location.y - this.location.y;
          const distance = Math.sqrt(dx * dx + dy * dy);

          if (distance > this.range) {
            const angle = Math.atan2(dy, dx);
            this.location.x += Math.cos(angle) * this.speed * deltaTime;
            this.location.y += Math.sin(angle) * this.speed * deltaTime;
          } else {
            this.isMoving = false;
          }
        }
      },

      canAttack: () => !this.isMoving && this.target && this.target.health > 0,

      attack: (target) => {
        target.takeDamage(this.attack);
        return true;
      },

      takeDamage: (amount) => {
        this.health -= amount;
        if (this.health <= 0) {
          this.health = 0;
        }
      },

      isDead: () => this.health <= 0
    };

    return unit;
  }

  findBuildLocation(player) {
    // Find valid location to build
    const radius = 3;
    const attempts = 20;

    for (let i = 0; i < attempts; i++) {
      const angle = Math.random() * Math.PI * 2;
      const distance = Math.random() * radius;
      const x = player.startLocation.x + Math.cos(angle) * distance;
      const y = player.startLocation.y + Math.sin(angle) * distance;

      if (this.mapManager.isWalkable(x, y)) {
        return { x, y, valid: true };
      }
    }

    return { valid: false };
  }

  selectBuildingType(player) {
    // Simple building selection based on what's missing
    if (!player.townHall) return 'townhall';

    const buildingCounts = {};
    player.buildings.forEach(building => {
      buildingCounts[building.type] = (buildingCounts[building.type] || 0) + 1;
    });

    if (!buildingCounts.barracks || buildingCounts.barracks < 2) {
      return 'barracks';
    } else if (!buildingCounts.farm) {
      return 'farm';
    } else if (!buildingCounts.mine) {
      return 'mine';
    }

    return null;
  }

  selectUnitType(player, buildingType) {
    const unitTypes = this.races[player.race].units;

    if (buildingType === 'barracks') {
      return unitTypes[0] || null;
    } else if (buildingType === 'townhall') {
      return unitTypes[1] || unitTypes[0] || null;
    }

    return unitTypes[0] || null;
  }

  findTarget(unit, enemyPlayer) {
    // Find nearest enemy unit
    let closest = null;
    let closestDistance = Infinity;

    enemyPlayer.units.forEach(enemyUnit => {
      if (!enemyUnit.isDead()) {
        const dx = unit.location.x - enemyUnit.location.x;
        const dy = unit.location.y - enemyUnit.location.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < closestDistance) {
          closest = enemyUnit;
          closestDistance = distance;
        }
      }
    });

    return closest;
  }

  updateAI() {
    // Update AI for all players
    Object.values(this.players).forEach(player => {
      if (player.id !== 'human') {
        this.updateAI(player, this.deltaTime);
      }
    });
  }

  startAI() {
    // Simple AI initialization
    // Could be enhanced with more sophisticated AI behavior
  }

  render() {
    // Render game state
    this.mapManager.render(this.engine.ctx);

    // Render all players' units and buildings
    Object.values(this.players).forEach(player => {
      player.units.forEach(unit => {
        if (!unit.isDead()) {
          this.renderUnit(unit, player.color);
        }
      });

      player.buildings.forEach(building => {
        this.renderBuilding(building, player.color);
      });
    });

    // Render UI
    this.uiManager.render(this.engine.ctx);

    // Render debug info
    this.renderDebugInfo();
  }

  renderUnit(unit, color) {
    const ctx = this.engine.ctx;\n    ctx.save();

    ctx.fillStyle = color || '#ffffff';
    ctx.fillRect(unit.location.x - 16, unit.location.y - 16, 32, 32);

    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 2;
    ctx.strokeRect(unit.location.x - 16, unit.location.y - 16, 32, 32);

    ctx.restore();
  }

  renderBuilding(building, color) {
    const ctx = this.engine.ctx;
    ctx.save();

    ctx.fillStyle = color || '#ffffff';
    ctx.fillRect(building.location.x - 32, building.location.y - 32, 64, 64);

    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 2;
    ctx.strokeRect(building.location.x - 32, building.location.y - 32, 64, 64);

    ctx.restore();
  }

  renderDebugInfo() {
    const ctx = this.engine.ctx;
    ctx.save();

    ctx.fillStyle = '#ffffff';
    ctx.font = '12px Arial';
    ctx.fillText(`Phase: ${this.currentPhase}`, 10, 20);
    ctx.fillText(`Turn: ${this.currentTurn}`, 10, 40);
    ctx.fillText(`Delta: ${this.deltaTime.toFixed(3)}s`, 10, 60);

    ctx.restore();
  }

  updateUI() {
    this.uiManager.updateGameState({
      currentPhase: this.currentPhase,
      players: this.players,
      resources: this.resources,
      selectedUnit: this.inputManager.getSelectedUnit(),
      selectedBuilding: this.inputManager.getSelectedBuilding()
    });
  }

  checkWinConditions() {
    const alivePlayers = Object.values(this.players).filter(p => p.townHall && p.townHall.health > 0);

    if (alivePlayers.length <= 1) {
      this.currentPhase = 'gameover';
      this.isRunning = false;

      if (this.gameLoopId) {
        cancelAnimationFrame(this.gameLoopId);
      }

      this.audioManager.stop('music');
      this.audioManager.play('gameover');

      this.uiManager.showGameOver(alivePlayers[0] || null);
    }
  }

  pause() {
    this.isRunning = false;
    this.currentPhase = 'paused';
    this.uiManager.setGameState(this.currentPhase);
  }

  resume() {
    if (this.currentPhase === 'paused') {
      this.isRunning = true;
      this.currentPhase = 'playing';
      this.lastTime = performance.now();
      this.gameLoop(this.lastTime);
      this.uiManager.setGameState(this.currentPhase);
    }
  }

  destroy() {
    if (this.gameLoopId) {
      cancelAnimationFrame(this.gameLoopId);
    }

    this.isRunning = false;
    this.engine.destroy();
    this.inputManager.destroy();
    this.audioManager.destroy();
  }

  resize(width, height) {
    this.config.width = width;
    this.config.height = height;
    this.engine.resize(width, height);
    this.uiManager.resize(width, height);
  }
}

export default Game;

"use strict";

class Engine {
  constructor(canvasId, width, height) {
    this.canvas = document.getElementById(canvasId);
    if (!this.canvas) {
      throw new Error(`Canvas with id '${canvasId}' not found`);
    }

    this.ctx = this.canvas.getContext('2d');
    this.width = width;
    this.height = height;
    this.lastFrameTime = 0;
    this.deltaTime = 0;

    this.initializeCanvas();
  }

  initializeCanvas() {
    this.canvas.width = this.width;
    this.canvas.height = this.height;
    this.canvas.style.position = 'absolute';
    this.canvas.style.top = '0';
    this.canvas.style.left = '0';
    this.canvas.style.width = '100%';
    this.canvas.style.height = '100%';
    this.canvas.style.imageRendering = 'pixelated';
    this.canvas.style.imageRendering = '-webkit-optimize-contrast';
  }

  clear() {
    this.ctx.clearRect(0, 0, this.width, this.height);
  }

  render() {
    // This is called by the game loop
    // Subclasses or mixins can override for custom rendering
  }

  resize(width, height) {
    this.width = width;
    this.height = height;
    this.canvas.width = width;
    this.canvas.height = height;
  }

  destroy() {
    this.ctx = null;
    this.canvas = null;
  }

  getDeltaTime() {
    return this.deltaTime;
  }

  updateDeltaTime(currentTime) {
    this.deltaTime = (currentTime - this.lastFrameTime) / 1000;
    this.lastFrameTime = currentTime;
  }
}

export default Engine;

"use strict";

class InputManager {
  constructor() {
    this.keys = {};
    this.mouse = {
      x: 0,
      y: 0,
      buttons: { left: false, right: false },
      wheel: 0
    };
    this.pointers = [];

    this.eventHandlers = {};

    this.initializeEventListeners();
  }

  initializeEventListeners() {
    // Keyboard events
    document.addEventListener('keydown', (e) => {
      this.keys[e.code] = true;
      this.emit('keyDown', e.code);
    });

    document.addEventListener('keyup', (e) => {
      this.keys[e.code] = false;
      this.emit('keyUp', e.code);
    });

    // Mouse events
    this.canvas = document.getElementById('game-canvas');
    if (this.canvas) {
      this.canvas.addEventListener('mousemove', (e) => {
        this.mouse.x = e.clientX;
        this.mouse.y = e.clientY;
        this.emit('mouseMove', { x: this.mouse.x, y: this.mouse.y });
      });

      this.canvas.addEventListener('mousedown', (e) => {
        this.mouse.buttons[Object.keys(this.mouse.buttons)[e.button]] = true;
        this.emit('mouseDown', {
          button: e.button,
          x: this.mouse.x,
          y: this.mouse.y
        });
      });

      this.canvas.addEventListener('mouseup', (e) => {
        this.mouse.buttons[Object.keys(this.mouse.buttons)[e.button]] = false;
        this.emit('mouseUp', {
          button: e.button,
          x: this.mouse.x,
          y: this.mouse.y
        });
      });

      this.canvas.addEventListener('wheel', (e) => {
        this.mouse.wheel = e.deltaY;
        this.emit('mouseWheel', { deltaY: e.deltaY });
      });
    }

    // Touch events for mobile
    document.addEventListener('touchstart', (e) => {
      e.preventDefault();
      this.pointers = Array.from(e.touches).map(touch => ({
        id: touch.identifier,
        x: touch.clientX,
        y: touch.clientY
      }));
      this.emit('touchStart', this.pointers);
    });

    document.addEventListener('touchmove', (e) => {
      e.preventDefault();
      this.pointers = Array.from(e.touches).map(touch => ({
        id: touch.identifier,
        x: touch.clientX,
        y: touch.clientY
      }));
      this.emit('touchMove', this.pointers);
    });

    document.addEventListener('touchend', (e) => {
      e.preventDefault();
      this.pointers = this.pointers.filter(p =>
        !Array.from(e.changedTouches).some(t => t.identifier === p.id)
      );
      this.emit('touchEnd', this.pointers);
    });
  }

  update(deltaTime) {
    // Update input state
    // Handle input combinations (Ctrl+A, etc.)
    // Process queued inputs
  }

  isKeyPressed(code) {
    return this.keys[code] || false;
  }

  isMouseButtonPressed(button) {
    return this.mouse.buttons[button] || false;
  }

  getMousePosition() {
    return { x: this.mouse.x, y: this.mouse.y };
  }

  getTouchPointers() {
    return this.pointers;
  }

  // Event handling
  on(event, callback) {
    if (!this.eventHandlers[event]) {
      this.eventHandlers[event] = [];
    }
    this.eventHandlers[event].push(callback);
  }

  off(event, callback) {
    if (this.eventHandlers[event]) {
      const index = this.eventHandlers[event].indexOf(callback);
      if (index > -1) {
        this.eventHandlers[event].splice(index, 1);
      }
    }
  }

  emit(event, data) {
    if (this.eventHandlers[event]) {
      this.eventHandlers[event].forEach(callback => {
        try {
          callback(data);
        } catch (error) {
          console.error(`Error in input handler for '${event}':`, error);
        }
      });
    }
  }

  destroy() {
    // Clean up event listeners
    this.keys = {};
    this.mouse = { x: 0, y: 0, buttons: { left: false, right: false }, wheel: 0 };
    this.pointers = [];
    this.eventHandlers = {};
  }

  // Unit selection utilities
  getSelectedUnit() {
    // Implementation would integrate with game selection system
    return null;
  }

  getSelectedBuilding() {
    // Implementation would integrate with game selection system
    return null;
  }
}

export default InputManager;

"use strict";

class ResourceManager {
  constructor() {
    this.resources = {};
    this.resourceRates = {};
    this.resourceSources = {};
    this.events = {};

    this.initializeResources();
  }

  initializeResources() {
    // Initialize resources with default values
    this.resources = {
      gold: { amount: 0, rate: 0, sources: [], max: 10000 },
      wood: { amount: 0, rate: 0, sources: [], max: 10000 },
      stone: { amount: 0, rate: 0, sources: [], max: 10000 },
      food: { amount: 0, rate: 0, sources: [], max: 1000 }
    };

    this.resourceRates = {
      gold: 0,
      wood: 0,
      stone: 0,
      food: 0
    };

    this.resourceSources = {
      gold: [],
      wood: [],
      stone: [],
      food: []
    };
  }

  addResourceSource(type, source) {
    if (!this.resourceSources[type]) {
      this.resourceSources[type] = [];
    }

    this.resourceSources[type].push(source);

    // Calculate total rate for this resource type
    this.updateResourceRate(type);
  }

  removeResourceSource(type, source) {
    if (this.resourceSources[type]) {
      const index = this.resourceSources[type].indexOf(source);
      if (index > -1) {
        this.resourceSources[type].splice(index, 1);
      }
      this.updateResourceRate(type);
    }
  }

  updateResourceRate(type) {
    const sources = this.resourceSources[type] || [];
    const totalRate = sources.reduce((sum, source) => sum + (source.getProductionRate ? source.getProductionRate() : 0), 0);
    this.resourceRates[type] = totalRate;
    this.resources[type].rate = totalRate;
  }

  update(deltaTime) {
    // Update all resource amounts based on production rates
    Object.keys(this.resources).forEach(resourceType => {
      const resource = this.resources[resourceType];
      const rate = this.resourceRates[resourceType];

      if (rate > 0) {
        const oldAmount = resource.amount;
        resource.amount += rate * deltaTime;

        // Cap at max amount
        if (resource.max && resource.amount > resource.max) {
          resource.amount = resource.max;
        }

        // Check if amount changed significantly
        if (Math.abs(resource.amount - oldAmount) > 0.1) {
          this.emit('resourceChanged', { type: resourceType, amount: resource.amount });
        }
      }
    });
  }

  getAmount(type) {
    return this.resources[type] ? this.resources[type].amount : 0;
  }

  getRate(type) {
    return this.resourceRates[type] || 0;
  }

  spend(type, amount) {
    if (this.resources[type] && this.resources[type].amount >= amount) {
      this.resources[type].amount -= amount;
      this.emit('resourceSpent', { type, amount });
      return true;
    }
    return false;
  }

  add(type, amount) {
    if (this.resources[type]) {
      this.resources[type].amount += amount;
      if (this.resources[type].max && this.resources[type].amount > this.resources[type].max) {
        this.resources[type].amount = this.resources[type].max;
      }
      this.emit('resourceAdded', { type, amount: this.resources[type].amount });
    }
  }

  canAfford(cost) {
    return Object.entries(cost).every(([type, amount]) =>
      this.resources[type] && this.resources[type].amount >= amount
    );
  }

  spendMultiple(cost) {
    return Object.entries(cost).every(([type, amount]) =>
      this.spend(type, amount)
    );
  }

  // Event handling
  on(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  off(event, callback) {
    if (this.events[event]) {
      const index = this.events[event].indexOf(callback);
      if (index > -1) {
        this.events[event].splice(index, 1);
      }
    }
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => {
        try {
          callback(data);
        } catch (error) {
          console.error(`Error in resource handler for '${event}':`, error);
        }
      });
    }
  }

  getAllResources() {
    const result = {};
    Object.keys(this.resources).forEach(type => {
      result[type] = {
        amount: this.resources[type].amount,
        rate: this.resourceRates[type],
        max: this.resources[type].max
      };
    });
    return result;
  }

  destroy() {
    this.resources = {};
    this.resourceRates = {};
    this.resourceSources = {};
    this.events = {};
  }
}

export default ResourceManager;

"use strict";

class MapManager {
  constructor(size, tileSize) {
    this.mapSize = size;
    this.tileSize = tileSize;
    this.terrain = [];
    this.buildings = [];
    this.units = [];
    this.resources = {};
    this.tileTypes = {
      grass: { walkable: true, renderable: true, color: '#2ECC71' },
      water: { walkable: false, renderable: true, color: '#3498DB' },
      mountain: { walkable: false, renderable: true, color: '#95A5A6' },
      forest: { walkable: true, renderable: true, color: '#27AE60' },
      building: { walkable: false, renderable: true, color: '#E67E22' },
      road: { walkable: true, renderable: true, color: '#ECF0F1' }
    };

    this.initializeMap();
  }

  initializeMap() {
    // Initialize empty terrain map
    this.terrain = Array(this.mapSize.height).fill().map(() =>
      Array(this.mapSize.width).fill(this.tileTypes.grass)
    );

    // Generate procedural terrain
    this.generateTerrain();
  }

  generateTerrain() {
    // Generate random terrain features
    const numWater = Math.floor(this.mapSize.width * this.mapSize.height * 0.2);
    const numMountains = Math.floor(this.mapSize.width * this.mapSize.height * 0.1);
    const numForests = Math.floor(this.mapSize.width * this.mapSize.height * 0.15);

    this.placeTerrainFeatures('water', numWater, 0.3);
    this.placeTerrainFeatures('mountain', numMountains, 0.4);
    this.placeTerrainFeatures('forest', numForests, 0.5);

    // Create roads between starting areas
    this.createStartingRoads();
  }

  placeTerrainFeatures(type, count, probability) {
    const tiles = this.mapSize.width * this.mapSize.height;
    const shuffled = Array(tiles).fill().map((_, i) => i);

    for (let i = 0; i < Math.min(count, shuffled.length); i++) {
      if (Math.random() < probability) {
        const index = shuffled[i];
        const x = index % this.mapSize.width;
        const y = Math.floor(index / this.mapSize.width);

        if (this.mapSize && this.terrain && y >= 0 && y < this.terrain.length && x >= 0 && x < this.terrain[y].length) {
          this.terrain[y][x] = this.tileTypes[type];
        }
      }
    }
  }

  createStartingRoads() {
    // Create starting areas and connecting roads
    const startX1 = Math.floor(this.mapSize.width * 0.2);
    const startY1 = Math.floor(this.mapSize.height * 0.7);
    const startX2 = Math.floor(this.mapSize.width * 0.8);
    const startY2 = Math.floor(this.mapSize.height * 0.3);

    // Create starting areas
    this.createStartingArea(startX1, startY1, '#2ECC71', 8);
    this.createStartingArea(startX2, startY2, '#E74C3C', 8);

    // Create connecting road
    this.createRoad(startX1 + 4, startY1, startX2 - 4, startY2, 'road');
  }

  createStartingArea(centerX, centerY, color, size) {
    for (let dx = -size; dx <= size; dx++) {
      for (let dy = -size; dy <= size; dy++) {
        const x = centerX + dx;
        const y = centerY + dy;

        if (this.isInBounds(x, y)) {
          if (Math.random() > 0.3) {
            this.terrain[y][x] = this.tileTypes.grass;
          }
        }
      }
    }
  }

  createRoad(startX, startY, endX, endY, type) {
    const dx = endX - startX;
    const dy = endY - startY;
    const distance = Math.sqrt(dx * dx + dy * dy);
    const steps = Math.ceil(distance);

    for (let i = 0; i < steps; i++) {
      const t = i / steps;
      const x = Math.round(startX + dx * t);
      const y = Math.round(startY + dy * t);

      if (this.isInBounds(x, y)) {
        this.terrain[y][x] = this.tileTypes[type];
      }
    }
  }

  isInBounds(x, y) {
    return x >= 0 && x < this.mapSize.width && y >= 0 && y < this.mapSize.height;
  }

  isWalkable(x, y) {
    if (!this.isInBounds(x, y)) return false;
    return this.terrain[y][x].walkable;
  }

  setTerrain(x, y, type) {
    if (this.isInBounds(x, y)) {
      this.terrain[y][x] = this.tileTypes[type] || this.tileTypes.grass;
    }
  }

  getTerrain(x, y) {
    if (this.isInBounds(x, y)) {
      return this.terrain[y][x];
    }
    return this.tileTypes.grass;
  }

  render(ctx) {
    // Render terrain
    for (let y = 0; y < this.mapSize.height; y++) {
      for (let x = 0; x < this.mapSize.width; x++) {
        const tile = this.terrain[y][x];
        if (tile.renderable) {
          ctx.fillStyle = tile.color;
          ctx.fillRect(x * this.tileSize, y * this.tileSize, this.tileSize, this.tileSize);

          // Add terrain-specific details
          if (tile.type === 'water') {
            ctx.fillStyle = 'rgba(52, 152, 219, 0.3)';
            ctx.beginPath();
            ctx.arc(
              (x + 0.5) * this.tileSize,
              (y + 0.5) * this.tileSize,
              this.tileSize * 0.4,
              0,
              Math.PI * 2
            );
            ctx.fill();
          }
        }
      }
    }

    // Render overlay objects (buildings, units, etc.)
    this.renderObjects(ctx);
  }

  renderObjects(ctx) {
    // Render buildings
    this.buildings.forEach(building => {
      const x = building.location.x;
      const y = building.location.y;
      ctx.save();

      // Building shadow
      ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
      ctx.fillRect(x * this.tileSize + 4, y * this.tileSize + 4, this.tileSize, this.tileSize);

      // Building body
      ctx.fillStyle = building.color || '#E67E22';
      ctx.fillRect(x * this.tileSize, y * this.tileSize, this.tileSize, this.tileSize);

      // Building border
      ctx.strokeStyle = '#2C3E50';
      ctx.lineWidth = 2;
      ctx.strokeRect(x * this.tileSize, y * this.tileSize, this.tileSize, this.tileSize);

      ctx.restore();
    });

    // Render units
    this.units.forEach(unit => {
      const x = unit.location.x;
      const y = unit.location.y;
      ctx.save();

      // Unit shadow
      ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
      ctx.fillRect(x * this.tileSize + 4, y * this.tileSize + 4, this.tileSize, this.tileSize);

      // Unit body
      ctx.fillStyle = unit.color || '#3498DB';
      ctx.fillRect(x * this.tileSize, y * this.tileSize, this.tileSize, this.tileSize);

      // Unit border
      ctx.strokeStyle = '#2C3E50';
      ctx.lineWidth = 2;
      ctx.strokeRect(x * this.tileSize, y * this.tileSize, this.tileSize, this.tileSize);

      ctx.restore();
    });
  }

  addBuilding(building) {
    this.buildings.push(building);
  }

  removeBuilding(building) {
    const index = this.buildings.indexOf(building);
    if (index > -1) {
      this.buildings.splice(index, 1);
    }
  }

  addUnit(unit) {
    this.units.push(unit);
  }

  removeUnit(unit) {
    const index = this.units.indexOf(unit);
    if (index > -1) {
      this.units.splice(index, 1);
    }
  }

  update(deltaTime) {
    // Update map logic
    // Regenerate resources based on terrain
    // Update fog of war if implemented
  }

  initializeTerrain(players) {
    // Initialize resources on map based on player positions
    players.forEach(player => {
      const radius = 5;
      const centerX = player.startLocation.x;
      const centerY = player.startLocation.y;

      for (let dx = -radius; dx <= radius; dx++) {
        for (let dy = -radius; dy <= radius; dy++) {
          const x = centerX + dx;
          const y = centerY + dy;

          if (this.isInBounds(x, y)) {
            if (Math.random() > 0.7) {
              this.setTerrain(x, y, 'mine');
            }
          }
        }
      }
    });
  }

  destroy() {
    this.terrain = [];
    this.buildings = [];
    this.units = [];
    this.resources = {};
  }
}

export default MapManager;

