    // Game over panel
    ctx.fillStyle = '#2c3e50';
    ctx.fillRect(
      this.gameOverScreen.x,
      this.gameOverScreen.y,
      this.gameOverScreen.width,
      this.gameOverScreen.height
    );

    ctx.strokeStyle = '#e74c3c';
    ctx.lineWidth = 3;
    ctx.strokeRect(
      this.gameOverScreen.x,
      this.gameOverScreen.y,
      this.gameOverScreen.width,
      this.gameOverScreen.height
    );

    // Title
